package com.ada.island;

import java.util.ArrayList;
import java.util.List;

/** Works without any API key: contextual questions generated by simple rules. */
public class SuggestionEngine {

    public static List<String> local(ContextReader.Ctx c) {
        List<String> out = new ArrayList<>();
        String app = c.appLabel == null ? "telefon" : c.appLabel;
        String low = app.toLowerCase();

        if (c.minutes >= 25 && isSocial(low)) {
            out.add(app + "'da " + c.minutes + " dakikadır geziyorsun. 5 dakika ara vermeye ne dersin?");
        }
        if (c.minutes >= 40) {
            out.add("Neredeyse " + c.minutes + " dakikadır " + app + " açık. Hâlâ doğru işte misin?");
        }
        if (c.battery >= 0 && c.battery <= 20 && !c.charging) {
            out.add("Batarya %" + c.battery + ". Şarj bulmadan önce bitirmen gereken tek iş ne?");
        }
        if (c.hour >= 23 || c.hour < 5) {
            out.add("Saat gece " + c.hour + ". Yarın için tek bir hedef seçip uyumaya ne dersin?");
        } else if (c.hour >= 6 && c.hour <= 10) {
            out.add("Gün yeni başladı: bugünün en önemli üç işi ne?");
        } else if (c.hour >= 15 && c.hour <= 17) {
            out.add("Öğleden sonra düşüşü başladı. 5 dakikalık bir yürüyüş iyi gelir mi?");
        }
        if (isVideo(low)) {
            out.add(app + "'da bir şeyler izliyorsun. Bunu not almaya değer bir fikir var mı?");
        }
        if (isWork(low)) {
            out.add(app + " üzerinde çalışıyorsun. Şu anki tek engelin ne?");
        }
        if (isMusicApp(low)) {
            out.add("Müzik açık. Bu şarkı çalışma moduna uygun mu, yoksa dikkatini mi dağıtıyor?");
        }

        out.add("Şu an " + app + " açıkken aklındaki asıl iş ne?");
        out.add("Bugün yapıp da bitirmediğin tek şey ne?");
        out.add("Şu anki ruh hâlini tek kelimeyle nasıl tarif edersin?");
        return out;
    }

    private static boolean isSocial(String s) {
        return s.contains("instagram") || s.contains("tiktok") || s.contains("twitter")
                || s.contains("x ") || s.equals("x") || s.contains("facebook") || s.contains("threads")
                || s.contains("snapchat") || s.contains("reddit") || s.contains("linkedin");
    }

    private static boolean isVideo(String s) {
        return s.contains("youtube") || s.contains("netflix") || s.contains("twitch") || s.contains("disney");
    }

    private static boolean isWork(String s) {
        return s.contains("slack") || s.contains("gmail") || s.contains("mail") || s.contains("docs")
                || s.contains("notion") || s.contains("drive") || s.contains("teams") || s.contains("zoom")
                || s.contains("meet") || s.contains("chrome") || s.contains("safari") || s.contains("git");
    }

    private static boolean isMusicApp(String s) {
        return s.contains("spotify") || s.contains("music") || s.contains("youtube music") || s.contains("deezer");
    }
}
